def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    while i < n:
        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < n:
                if line[i] == '"':
                    i += 1
                    if i < n and line[i] == '"':
                        # Doubled quote, represents a single quote
                        field.append('"')
                        i += 1
                    else:
                        # End of quoted field
                        if i < n and line[i] != ',':
                            # Closing quote not followed by comma or end of line
                            return None
                        if i < n:
                            i += 1  # Skip the comma
                        break
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
            fields.append(''.join(field))
        else:
            # Unquoted field
            field = []
            while i < n and line[i] != ',':
                if line[i] == '"':
                    # Double quote in unquoted field is malformed
                    return None
                field.append(line[i])
                i += 1
            fields.append(''.join(field))
            if i < n:
                i += 1  # Skip the comma

    return fields

